fixtures.content:
# Shared by the cases of this file, sourced as: . {{FIX}}/lib.sh {{ROOT}} {{CLAUDE}} {{FIX}}/{{SID}}
# (the harness root, its .claude folder, a folder of the case's own).
H=$1; C=$2; F=$3
if [ "$(id -u)" = 0 ] && id node >/dev/null 2>&1 && command -v gosu >/dev/null 2>&1 && [ -z "${EVAL_AS_NODE:-}" ]; then
  # Root (the image build) runs the case as node, the user of a workshop, as sync-harness.sh would.
  mkdir -p "$F" && chown node "$F" && exec gosu node env EVAL_AS_NODE=1 bash -c "$BASH_EXECUTION_STRING"
  exit 1
fi
python3 -c 'import yaml' 2>/dev/null || { printf 'ok (skipped: PyYAML is missing)'; exit 0; }
TOOL=$C/skills/workshop-profile/scripts/workshop-profile.py
PROF=$H/profiles; [ -d "$PROF/packs" ] || PROF=$C/harness/profiles
SYNC=$H/../sync-harness.sh; [ -f "$SYNC" ] || SYNC=$(command -v sync-harness.sh 2>/dev/null) || SYNC=""
mkdir -p "$F" || exit 1
STG=$F/stg
GITC=(-c user.email=eval@example.invalid -c user.name=eval -c init.defaultBranch=main)
export HARNESS_STAGING=$STG HARNESS_IMAGE_MANIFEST=$F/none.manifest SKILLS_LEGACY_MANIFEST=$F/none.legacy \
       HARNESS_LEGACY_WORKSPACE=$F/legacy HARNESS_SYNC_SCRIPT=${SYNC:-$F/no-sync.sh}
fail() { printf '%s' "$*"; exit 1; }
need_sync() { [ -n "$SYNC" ] || { printf 'ok (skipped: sync-harness.sh is not reachable from this layout)'; exit 0; }; }
put() { mkdir -p "$(dirname "$STG/$1")" && printf '%s\n' "${2:-$1}" > "$STG/$1"; }
# A staging: the real definitions and switcher, and stand-in files for every pack.
mkstg() {
  mkdir -p "$STG/claude/skills" && cp -r "$PROF" "$STG/profiles" && cp -r "$C/skills/workshop-profile" "$STG/claude/skills/" || exit 1
  put claude/settings.json '{}'; put claude/hooks/probe.sh '#!/bin/bash'; put claude/lib/probe.sh '#!/bin/bash'
  put HARNESS.md; put claude/skills/team-probe/SKILL.md; put references/probe.md
  put claude/CLAUDE.workshop.md '@.claude/harness/HARNESS.md'; put claude/settings.local.seed.json '{}'
  put packs/source/claude/rules/source-space.md
  for p in contrib dev quality release docs-audit usage; do put "packs/$p/claude/skills/$p-probe/SKILL.md"; done
  put packs/usage/claude/skills/token-usage/SKILL.md; put packs/dev/claude/agents/dev-probe.md
  put packs/repo-orkeon/references/repo.yaml 'product: Orkeon'; put packs/repo-orkeon/claude/rules/orkeon-probe.md
  put packs/repo-orkeon-workshop/claude/rules/ws-probe.md
}
mkws() { mkdir -p "$1/teams" || exit 1; }
mkrepo() {   # $1 folder, $2 origin URL: one commit, one tracked README.md
  mkdir -p "$1" && git -C "$1" "${GITC[@]}" init -q && git -C "$1" remote add origin "$2" && printf 'x\n' > "$1/README.md" \
    && git -C "$1" add README.md && git -C "$1" "${GITC[@]}" commit -qm init || exit 1
}
wp() { env ORKEON_WORKSHOP="$1" python3 "$TOOL" "${@:2}" 2>&1; }
sy() { env ORKEON_WORKSHOP="$1" bash "$SYNC" "${@:2}" 2>&1 | grep -v setlocale; return "${PIPESTATUS[0]}"; }
# The effective packs a dry run announces, or `refused`.
packs_of() { wp "$@" --dry-run | head -n 1 | sed -n -e 's/.* - packs \([^;]*\)\(;.*\)\{0,1\}\.$/\1/p' -e '/fits here/s/.*/refused/p'; }
table() { local p out=""; for p in user contrib dev release docs all; do out="$out$p=$(packs_of "$1" "$p")|"; done; printf '%s' "$out"; }
# Every path and its content under a folder (.git aside): equal before and after means nothing written.
snap() { (cd "$1" && find . -path ./.git -prune -o -type f -print0 | LC_ALL=C sort -z | xargs -0 -r md5sum; find . -path ./.git -prune -o -print | LC_ALL=C sort) | md5sum; }

cases.cmd:
. {{FIX}}/lib.sh {{ROOT}} {{CLAUDE}} {{FIX}}/{{SID}}
[ -d "$H/profiles/packs" ] || { printf 'ok (skipped: the harness tree is not here)'; exit 0; }
out=$(HARNESS_STAGING=$H python3 "$TOOL" --check 2>&1) || fail "$out"
printf '%s' "$out" | grep -q '^workshop-profile: check: every file belongs to exactly one pack' || fail "$out"
printf 'ok'
